    String admin(String role){AdminUser a=new AdminUser();a.setAccount("trader_qa_"+UUID.randomUUID());a.setEmail(a.getAccount()+"@example.invalid");a.setRole(role);a.setEnabled(true);a.setPasswordHash("TEST_ONLY");a.setCurrentToken(UUID.randomUUID().toString());a=admins.saveAndFlush(a);names.register("ADMIN",a.getId(),a.getAccount());Map<String,Object> claims=new HashMap<>();claims.put("userType","admin");claims.put("sid",a.getCurrentToken());claims.put("credential",jwt.credentialKey(a.getPasswordHash()));return jwt.generateToken("admin-"+a.getId(),claims);}
